insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  19,
  $wyb$A GitHub App that listens for pull_request webhook events, fetches the diff, sends each changed file to the AI for review, parses the response into per-line comments, posts them inline on the PR, and adds a summary comment with a quality score. A line-number guard drops any comment whose line isn't actually part of the diff, since the AI can't have legitimately reviewed a line it was never shown -- and the bot ships forced into comment-only mode until you've confirmed its findings are useful.$wyb$,
  $wyl$[
  "Verify a GitHub webhook signature with real HMAC math, including why compare_digest matters over ==",
  "Build and verify a GitHub App JWT against a real RSA keypair",
  "Fetch a PR's changed files and diffs via the GitHub API",
  "Parse a unified diff's hunk headers to know which line numbers are actually valid to comment on",
  "Engineer a code-review prompt that returns structured, defensively-parsed findings",
  "Compute a transparent quality score and a safe-by-default approve/comment/request-changes decision"
]$wyl$::jsonb,
  $sess${
  "model": "Gemini 3.7 Flash or Claude Haiku 4.5 (your choice - see sdt_ai.py setup)",
  "totalTime": "150 min",
  "buildCount": 4,
  "whatYouNeed": [
    "A free Gemini API key (aistudio.google.com/apikey) OR your own Claude/Anthropic API key (console.anthropic.com/settings/keys)",
    "Python 3.10+ installed",
    "A GitHub account and a throwaway test repository for development",
    "ngrok for receiving webhooks locally"
  ],
  "outcomes": [
    "Register a GitHub App and verify its webhook signatures with real HMAC math",
    "Build and verify a GitHub App JWT against a real RSA keypair before ever touching a live account",
    "Fetch a PR's changed files and diffs via the GitHub API",
    "Have the AI review each file for bugs, security issues, performance, and readability",
    "Drop any AI comment that cites a line number outside the actual diff, instead of trusting it blindly",
    "Post inline comments and a transparent quality score, safely defaulted to comment-only"
  ],
  "builds": [
    {
      "number": 1,
      "title": "Register your GitHub App and verify webhooks",
      "time": "35 min",
      "description": "Get GitHub talking to your local machine before writing any review logic.",
      "steps": [
        {
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future AI Builder project:",
          "prompt": "\"\"\"\nSocial Dev AI Builder - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# gemini-3.7-flash first - the current stable/GA flash model. If it's\n# ever down (Google's free tier occasionally returns 503 \"high demand\"\n# on a single model for hours at a time), gemini-2.5-flash is a real\n# fallback, not a downgrade-and-forget: a different model is a\n# different capacity pool, so it's often still up during a\n# 3.7-specific outage. Set GEMINI_MODEL in .env to pin one specific\n# model instead and skip the fallback entirely.\n_env_model = os.environ.get(\"GEMINI_MODEL\")\nGEMINI_MODELS = [_env_model] if _env_model else [\"gemini-3.7-flash\", \"gemini-2.5-flash\"]\nGEMINI_URL_TEMPLATE = \"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent\"\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Gemini's free tier occasionally answers 503 (\"model overloaded\") during\n# busy periods - that's not your code being wrong, retrying a couple of\n# times almost always gets a real answer.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini_model(model, api_key, payload):\n    \"\"\"\n    Tries ONE Gemini model, retrying up to MAX_ATTEMPTS times on a 503\n    (\"high demand\") before giving up on this model. Returns the parsed\n    result dict, or raises AIError - including a distinct AIError for a\n    503 that never cleared, so _ask_gemini() below can tell \"this model\n    is down, try the next one\" apart from every other failure.\n    \"\"\"\n    url = GEMINI_URL_TEMPLATE.format(model=model)\n\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(url, params={\"key\": api_key}, json=payload, timeout=90)\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            )\n\n        if response.status_code == 503:\n            if attempt < MAX_ATTEMPTS - 1:\n                time.sleep(RETRY_DELAY_SECONDS)\n                continue\n            raise AIError(f\"{model} is busy (503 - high demand)\")\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again.\"\n            )\n\n        if response.status_code == 400:\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        try:\n            candidate = data[\"candidates\"][0]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n\n        if candidate.get(\"finishReason\") == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        try:\n            text = candidate[\"content\"][\"parts\"][0][\"text\"]\n        except (KeyError, IndexError):\n            raise AIError(f\"Unexpected reply shape from Gemini: {data}\")\n\n        usage = data.get(\"usageMetadata\", {})\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": {\"maxOutputTokens\": max_tokens},\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    # Try each model in GEMINI_MODELS in order - a 503 that survives every\n    # retry on one model falls through to the next, since a different\n    # model is a different capacity pool and is often still up during a\n    # model-specific outage. Any other kind of failure (bad key, rate\n    # limit, safety block) is raised immediately instead of wasted on a\n    # second model that would fail the exact same way.\n    last_problem = None\n    for model in GEMINI_MODELS:\n        try:\n            return _ask_gemini_model(model, api_key, payload)\n        except AIError as problem:\n            if \"high demand\" not in str(problem):\n                raise\n            last_problem = problem\n\n    raise AIError(\n        f\"Gemini was unavailable after trying {', '.join(GEMINI_MODELS)} ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    try:\n        response = requests.post(\n            ANTHROPIC_URL,\n            headers={\n                \"x-api-key\": api_key,\n                \"anthropic-version\": ANTHROPIC_VERSION,\n                \"Content-Type\": \"application/json\",\n            },\n            json=payload,\n            timeout=90,\n        )\n    except requests.RequestException:\n        raise AIError(\"Could not reach Claude. Check your internet connection and try again.\")\n\n    try:\n        data = response.json()\n    except ValueError:\n        raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\")\n\n    if response.status_code == 401:\n        raise AIError(\n            \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n        )\n\n    if response.status_code == 429:\n        raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n    if \"error\" in data:\n        raise AIError(data[\"error\"].get(\"message\", str(data[\"error\"])))\n\n    text = \"\".join(\n        block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n    )\n    usage = data.get(\"usage\", {})\n    return {\n        \"text\": text,\n        \"input_tokens\": usage.get(\"input_tokens\"),\n        \"output_tokens\": usage.get(\"output_tokens\"),\n    }\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI Builder connection...\\n\")\n    try:\n        provider = _get_provider()\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider}\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first."
        },
        {
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:",
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n\n# GitHub App - create at Settings > Developer Settings > GitHub Apps\nGITHUB_APP_ID=paste_your_app_id_here\nWEBHOOK_SECRET=choose_your_own_random_string_here\n\n# Download your App's private key (.pem) and save it as\n# private-key.pem in this same folder\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented."
        },
        {
          "instruction": "In GitHub Settings > Developer Settings > GitHub Apps, create a new app with: Webhook URL pointing to your ngrok URL + /webhook, the webhook secret from your .env, and read/write permissions on Pull Requests and Contents. Subscribe to the \"Pull request\" event. Generate a private key (.pem) and install the app on your test repository. Note the App ID and Installation ID.",
          "verify": "Run `ngrok http 5000` and confirm your GitHub App's webhook URL is set to <ngrok-url>/webhook."
        },
        {
          "instruction": "Create `webhook.py` with this code, then start it:",
          "prompt": "\"\"\"\nStep 1 of the Code Review Agent.\n\nReceives GitHub's pull_request webhook and verifies its signature\nbefore trusting anything in the payload. The signature check is a pure\nfunction tested below with real HMAC math - no Flask server, no ngrok,\nno GitHub account needed to prove it works.\n\"\"\"\n\nimport hashlib\nimport hmac\nimport os\nimport sys\n\nfrom dotenv import load_dotenv\nfrom flask import Flask, request\n\nload_dotenv()\n\napp = Flask(__name__)\n\nRELEVANT_ACTIONS = {\"opened\", \"synchronize\"}\n\n\ndef verify_signature(payload_body, signature_header, secret):\n    \"\"\"\n    Returns True if signature_header (GitHub's X-Hub-Signature-256\n    value) matches an HMAC-SHA256 of payload_body computed with secret.\n\n        verify_signature(b'{\"action\": \"opened\"}', \"sha256=abc123...\", \"my-secret\")\n\n    Uses hmac.compare_digest rather than == specifically to avoid a\n    timing attack - a plain == comparison returns as soon as the first\n    byte differs, which leaks (via response time) how many leading bytes\n    of a guessed signature were correct. compare_digest always takes the\n    same time regardless of where the strings diverge.\n    \"\"\"\n    if not signature_header or not signature_header.startswith(\"sha256=\"):\n        return False\n\n    expected = \"sha256=\" + hmac.new(secret.encode(), payload_body, hashlib.sha256).hexdigest()\n    return hmac.compare_digest(expected, signature_header)\n\n\n@app.route(\"/webhook\", methods=[\"POST\"])\ndef webhook():\n    signature = request.headers.get(\"X-Hub-Signature-256\", \"\")\n    secret = os.environ[\"WEBHOOK_SECRET\"]\n\n    if not verify_signature(request.data, signature, secret):\n        return \"Invalid signature\", 401\n\n    payload = request.get_json()\n    if payload.get(\"action\") in RELEVANT_ACTIONS:\n        print(f\"Received a relevant PR event: {payload['action']} on PR #{payload['pull_request']['number']}\")\n        # review_pr(payload) is wired in from Build 2 onward.\n\n    return \"\", 200\n\n\nif __name__ == \"__main__\":\n    if \"--selftest\" in sys.argv:\n        secret = \"my-secret\"\n        body = b'{\"action\": \"opened\"}'\n        correct_sig = \"sha256=\" + hmac.new(secret.encode(), body, hashlib.sha256).hexdigest()\n\n        assert verify_signature(body, correct_sig, secret) is True\n        print(\"Correct signature verified successfully.\")\n\n        assert verify_signature(body, \"sha256=wrongvalue\", secret) is False\n        print(\"Incorrect signature correctly rejected.\")\n\n        assert verify_signature(body, \"\", secret) is False\n        print(\"Missing signature correctly rejected.\")\n\n        tampered_body = b'{\"action\": \"closed\"}'\n        assert verify_signature(tampered_body, correct_sig, secret) is False\n        print(\"Tampered payload correctly rejected (signature no longer matches).\")\n\n        print(\"\\\\nAll signature checks passed.\")\n    else:\n        app.run(port=5000)\n",
          "verify": "Run `python webhook.py --selftest` first (real HMAC math, no Flask server, no network). You should see the correct signature verified, an incorrect one rejected, a missing one rejected, and a tampered payload rejected - ending with `All signature checks passed.` Then run `python webhook.py` (no flag) to start the real server, and open a test PR in your repo - your console should print the relevant PR event."
        }
      ],
      "goFurther": "Temporarily change one character of WEBHOOK_SECRET in .env (but not in your GitHub App's settings) and open another test PR - confirm the endpoint returns 401. This proves the verification is actually doing something, not just always returning True."
    },
    {
      "number": 2,
      "title": "Authenticate and fetch the PR diff",
      "time": "30 min",
      "description": "Get the actual code changes the AI will review.",
      "steps": [
        {
          "instruction": "Create `github_client.py` with this code:",
          "prompt": "\"\"\"\nStep 2 of the Code Review Agent.\n\nAuthenticates as your GitHub App and fetches a PR's changed files. JWT\nconstruction is a pure function you can inspect and verify the shape\nof without a real private key or network call - only the token\nexchange and file fetch need your actual GitHub App credentials.\n\"\"\"\n\nimport time\n\nimport jwt\nimport requests\n\nGITHUB_API = \"https://api.github.com\"\n\n\ndef build_jwt(app_id, private_key, now=None):\n    \"\"\"\n    Builds a signed JWT for authenticating as your GitHub App (RS256,\n    10-minute expiry, per GitHub's requirements).\n\n        token = build_jwt(app_id, private_key)\n\n    Pure function given a fixed `now` - tested below with a real RSA\n    keypair generated on the fly, so the test proves the JWT actually\n    decodes and carries the right claims, not just that this function\n    runs without an exception.\n    \"\"\"\n    now = now or int(time.time())\n    payload = {\n        \"iat\": now - 60,   # backdated 60s - GitHub's own recommendation, to tolerate clock drift\n        \"exp\": now + 600,  # 10-minute expiry, GitHub's maximum\n        \"iss\": app_id,\n    }\n    return jwt.encode(payload, private_key, algorithm=\"RS256\")\n\n\ndef get_installation_token(app_id, private_key, installation_id):\n    \"\"\"\n    Exchanges a freshly-built JWT for a short-lived installation access\n    token - this is the token that actually authorizes API calls like\n    fetching PR files or posting a review.\n    \"\"\"\n    app_jwt = build_jwt(app_id, private_key)\n    response = requests.post(\n        f\"{GITHUB_API}/app/installations/{installation_id}/access_tokens\",\n        headers={\"Authorization\": f\"Bearer {app_jwt}\", \"Accept\": \"application/vnd.github+json\"},\n    )\n    response.raise_for_status()\n    return response.json()[\"token\"]\n\n\ndef get_pr_files(token, repo, pr_number):\n    \"\"\"\n    Fetches the list of changed files for one PR, each with its diff\n    patch.\n\n        files = get_pr_files(token, \"yourname/yourrepo\", 42)\n        -> [{\"filename\": \"auth.py\", \"patch\": \"@@ ...\"}, ...]\n    \"\"\"\n    response = requests.get(\n        f\"{GITHUB_API}/repos/{repo}/pulls/{pr_number}/files\",\n        headers={\"Authorization\": f\"Bearer {token}\", \"Accept\": \"application/vnd.github+json\"},\n    )\n    response.raise_for_status()\n    return [{\"filename\": f[\"filename\"], \"patch\": f.get(\"patch\", \"\")} for f in response.json()]\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the JWT is built correctly - a\n    # throwaway RSA keypair, no GitHub account or network call needed:\n    #     python github_client.py\n    from cryptography.hazmat.primitives import serialization\n    from cryptography.hazmat.primitives.asymmetric import rsa\n\n    key = rsa.generate_private_key(public_exponent=65537, key_size=2048)\n    private_pem = key.private_bytes(\n        encoding=serialization.Encoding.PEM,\n        format=serialization.PrivateFormat.TraditionalOpenSSL,\n        encryption_algorithm=serialization.NoEncryption(),\n    ).decode()\n    public_pem = key.public_key().public_bytes(\n        encoding=serialization.Encoding.PEM,\n        format=serialization.PublicFormat.SubjectPublicKeyInfo,\n    ).decode()\n\n    fixed_now = 1_700_000_000\n    token = build_jwt(\"12345\", private_pem, now=fixed_now)\n\n    decoded = jwt.decode(token, public_pem, algorithms=[\"RS256\"], options={\"verify_exp\": False})\n    assert decoded[\"iss\"] == \"12345\"\n    assert decoded[\"iat\"] == fixed_now - 60\n    assert decoded[\"exp\"] == fixed_now + 600\n    print(\"JWT decoded correctly:\", decoded)\n\n    print(\"\\nAll checks passed. This JWT would be accepted by GitHub as proof you control app 12345's private key.\")\n",
          "verify": "Run `python github_client.py` (a throwaway RSA keypair generated on the fly - no GitHub account or network call needed). You should see the JWT decoded back with the correct app id, iat, and exp claims, ending with `All checks passed.`"
        },
        {
          "instruction": "Now update `webhook.py`'s webhook() function to call review_pr(payload) instead of just printing, and add a temporary review_pr() that fetches and prints each file's patch length:",
          "prompt": "def review_pr(payload):\n    from github_client import get_installation_token, get_pr_files\n    repo = payload[\"repository\"][\"full_name\"]\n    pr_number = payload[\"pull_request\"][\"number\"]\n    installation_id = payload[\"installation\"][\"id\"]\n\n    app_id = os.environ[\"GITHUB_APP_ID\"]\n    with open(\"private-key.pem\") as f:\n        private_key = f.read()\n\n    token = get_installation_token(app_id, private_key, installation_id)\n    files = get_pr_files(token, repo, pr_number)\n    for file in files:\n        print(file[\"filename\"], \"-\", len(file[\"patch\"]), \"characters\")",
          "verify": "Open another test PR with a small code change. Your server should print the changed filename(s) and a non-zero patch length for each. If you get a 401 from GitHub, double-check the private key and App ID match your GitHub App exactly."
        }
      ],
      "goFurther": "Open a PR that changes 3+ files - confirm get_pr_files() returns all of them, not just the first."
    },
    {
      "number": 3,
      "title": "Build the reviewer with a line-number guard",
      "time": "45 min",
      "description": "This is where the actual code review happens. It's also where the project's core safety guard lives: a comment whose line number isn't actually part of the diff is dropped, since the AI can't have legitimately reviewed a line it was never shown.",
      "steps": [
        {
          "instruction": "Create `reviewer.py` with this code:",
          "prompt": "\"\"\"\nStep 3 of the Code Review Agent.\n\nThis is where the actual code review happens. The AI's JSON reply is\nparsed defensively (a stray code fence is stripped, not fatal), and the\nline-number guard here is the project's core safety feature: any\ncomment whose line number isn't actually part of the diff is dropped,\nsince the AI can't have legitimately reviewed a line it was never shown.\n\"\"\"\n\nimport json\nimport re\n\nfrom sdt_ai import ask_ai\n\nSEVERITIES = {\"low\", \"medium\", \"high\"}\n\n\ndef build_prompt(filename, patch):\n    return f\"\"\"Review this diff for bugs, security issues, performance problems,\nand readability. Prioritize bugs, security, and performance - do not\nflag pure style preferences.\n\nFile: {filename}\nDiff:\n{patch}\n\nReturn ONLY this JSON shape, no markdown code fence, no explanation:\n{{\"comments\": [{{\"line\": <line number in the diff>, \"severity\": \"low|medium|high\", \"comment\": \"...\"}}], \"summary\": \"one sentence\"}}\n\nIf there are no issues, return {{\"comments\": [], \"summary\": \"Looks good\"}}.\"\"\"\n\n\ndef parse_review_reply(reply):\n    \"\"\"\n    Turns the AI's reply into {\"comments\": [...], \"summary\": \"...\"},\n    tolerating a code fence and dropping any comment with an\n    unrecognised severity.\n\n        parse_review_reply('```json\\\\n{\"comments\": [], \"summary\": \"Looks good\"}\\\\n```')\n\n    Returns None (never raises) if the reply isn't valid JSON at all.\n    \"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        data = json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n\n    comments = [\n        c for c in data.get(\"comments\", [])\n        if isinstance(c.get(\"line\"), int) and c.get(\"severity\") in SEVERITIES\n    ]\n    return {\"comments\": comments, \"summary\": data.get(\"summary\", \"\")}\n\n\ndef valid_line_numbers(patch):\n    \"\"\"\n    Parses a unified diff patch (GitHub's `files[].patch` field) and\n    returns the set of NEW-file line numbers that actually appear in the\n    diff - only these are valid positions for a GitHub PR review comment.\n\n        valid_line_numbers(\"@@ -1,3 +1,4 @@\\\\n def foo():\\\\n-    return 1\\\\n+    return 2\\\\n+    # comment\")\n        -> {1, 2, 3}\n    \"\"\"\n    valid = set()\n    new_line = None\n    for line in patch.splitlines():\n        if line.startswith(\"@@\"):\n            match = re.search(r\"\\+(\\d+)\", line)\n            new_line = int(match.group(1)) if match else None\n            continue\n        if new_line is None:\n            continue\n        if line.startswith(\"-\"):\n            continue\n        valid.add(new_line)\n        new_line += 1\n    return valid\n\n\ndef filter_valid_comments(comments, patch):\n    \"\"\"\n    Drops any comment whose line number isn't actually part of the diff.\n\n    This is the project's core safety guard: the AI is asked for a line\n    number inside the diff, but nothing stops it from citing a line\n    outside the changed range - hallucinating a line further down an\n    unchanged part of the file it never actually saw. A comment on a\n    line GitHub's API would reject anyway is worse than no comment - it\n    would silently fail to post instead of flagging the real issue.\n    \"\"\"\n    valid_lines = valid_line_numbers(patch)\n    kept = []\n    for comment in comments:\n        if comment[\"line\"] in valid_lines:\n            kept.append(comment)\n        else:\n            print(f\"  Dropped a comment on line {comment['line']} - not part of this diff.\")\n    return kept\n\n\ndef review_file(filename, patch):\n    \"\"\"\n    The main function. Give it one changed file's name and patch, get\n    back {\"comments\": [...], \"summary\": \"...\"} with every comment's\n    line number validated against the actual diff.\n    \"\"\"\n    prompt = build_prompt(filename, patch)\n    reply = ask_ai(prompt, max_tokens=1500, project=\"code-review-agent\")\n\n    parsed = parse_review_reply(reply)\n    if parsed is None:\n        raise ValueError(\n            \"The AI's reply wasn't valid JSON.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    parsed[\"comments\"] = filter_valid_comments(parsed[\"comments\"], patch)\n    return parsed\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check parsing and the line-number\n    # guard work - no AI call, no credits spent:  python reviewer.py\n\n    SAMPLE_PATCH = \"@@ -1,3 +1,4 @@\\n def foo():\\n-    return 1\\n+    return 2\\n+    # comment\"\n\n    print(\"Checking valid_line_numbers()...\")\n    lines = valid_line_numbers(SAMPLE_PATCH)\n    assert lines == {1, 2, 3}\n    print(\"  OK -\", lines)\n\n    print(\"\\nChecking parse_review_reply() with a clean reply...\")\n    clean_reply = '{\"comments\": [{\"line\": 2, \"severity\": \"high\", \"comment\": \"hardcoded value\"}], \"summary\": \"One issue found\"}'\n    result = parse_review_reply(clean_reply)\n    assert len(result[\"comments\"]) == 1\n    print(\"  OK -\", result)\n\n    print(\"\\nChecking a ```json-fenced reply gets stripped correctly...\")\n    fenced = '```json\\n{\"comments\": [], \"summary\": \"Looks good\"}\\n```'\n    assert parse_review_reply(fenced) == {\"comments\": [], \"summary\": \"Looks good\"}\n    print(\"  OK\")\n\n    print(\"\\nChecking a comment with an invalid severity gets dropped by parse_review_reply()...\")\n    bad_severity = '{\"comments\": [{\"line\": 2, \"severity\": \"critical\", \"comment\": \"x\"}], \"summary\": \"...\"}'\n    assert parse_review_reply(bad_severity)[\"comments\"] == []\n    print(\"  OK - unrecognised severity 'critical' correctly dropped\")\n\n    print(\"\\nChecking filter_valid_comments() drops an out-of-range line number...\")\n    comments = [\n        {\"line\": 2, \"severity\": \"high\", \"comment\": \"real issue, line 2 is in the diff\"},\n        {\"line\": 999, \"severity\": \"high\", \"comment\": \"hallucinated - line 999 was never in this diff\"},\n    ]\n    kept = filter_valid_comments(comments, SAMPLE_PATCH)\n    assert len(kept) == 1\n    assert kept[0][\"line\"] == 2\n    print(\"  OK - the out-of-range comment was dropped, the real one was kept\")\n\n    print(\"\\nChecking a reply that isn't JSON at all...\")\n    assert parse_review_reply(\"Sorry, I can't review that.\") is None\n    print(\"  OK - returned None instead of crashing\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python reviewer.py` (no AI call, no credits spent - this only tests parsing and the line-number guard against fake data). You should see the diff's valid line numbers correctly computed as {1, 2, 3}, a clean reply and a ```json-fenced reply both parsed correctly, an invalid severity correctly dropped, an out-of-range line number correctly dropped while a real one is kept, and a non-JSON reply correctly returning None - ending with `All checks passed.`"
